  /// Hub sequence of the last applied op.
  final int syncSeq;
  final bool deleted;
  final String name;
  final String? nickname;
  final String role;
  final int color;
  final String? emoji;
  final String? avatarBlob;
  final String? birthday;
  final String? kidStage;
